import numpy as np

def equalize(gray, levels=256):
    hist, _ = np.histogram(gray, bins=levels, range=(0, levels-1))
    cdf = hist.cumsum() / hist.sum()
    return np.interp(gray, np.arange(levels), (levels-1)*cdf)

class PID:
    def __init__(self, kp, ki, kd):
        self.kp, self.ki, self.kd = kp, ki, kd
        self.i = 0.0
        self.prev = 0.0
    def update(self, e, dt):
        self.i += e * dt
        d = (e - self.prev) / dt
        self.prev = e
        return self.kp*e + self.ki*self.i + self.kd*d

